package ro.leo.visual;
import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;
/** Regular files only. Never overwrites; cross-volume moves verify a copy before deleting source. */
final class FileTransfers {
    static final long MAX_BYTES=2L*1024*1024*1024;
    static boolean inside(File root,File file)throws IOException{String a=root.getCanonicalPath(),b=file.getCanonicalPath();return b.equals(a)||b.startsWith(a+File.separator);}
    static String digest(File file)throws IOException{return digest(file,null,0,file.length());}
    private static String digest(File file,Progress progress,long offset,long total)throws IOException{try{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] bytes=new byte[65536];int n;long done=0;while((n=in.read(bytes))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();digest.update(bytes,0,n);done+=n;if(progress!=null)progress.update(offset+done,total,"Verificare SHA-256");}}StringBuilder value=new StringBuilder();for(byte b:digest.digest())value.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return value.toString();}catch(NoSuchAlgorithmException e){throw new IOException(e);}}
    interface Progress{void update(long done,long total,String phase);}
    static File transfer(File sourceRoot,File source,File destinationRoot,File folder,boolean move)throws IOException{return transfer(sourceRoot,source,destinationRoot,folder,move,null);}
    static File transfer(File sourceRoot,File source,File destinationRoot,File folder,boolean move,Progress progress)throws IOException{
        if(!inside(sourceRoot,source)||!inside(destinationRoot,folder)||!folder.isDirectory()||!source.isFile()||Files.isSymbolicLink(source.toPath()))throw new IOException("Fișier sau destinație invalidă");
        File target=new File(folder,source.getName());if(!inside(destinationRoot,target)||target.exists())throw new IOException("Numele există deja");long size=source.length(),modified=source.lastModified();if(size>MAX_BYTES)throw new IOException("Limita este 2 GiB pe fișier");if(folder.getUsableSpace()<size+1048576)throw new IOException("Spațiu insuficient");File temporary=File.createTempFile(".leo-copy-",".part",folder);
        try{try(InputStream in=new FileInputStream(source);FileOutputStream out=new FileOutputStream(temporary)){byte[] bytes=new byte[65536];int n;long written=0;while((n=in.read(bytes))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();written+=n;if(written>MAX_BYTES)throw new IOException("Fișierul a crescut peste limită");out.write(bytes,0,n);if(progress!=null)progress.update(written,size,"Copiere");}out.getFD().sync();}
            if(progress!=null)progress.update(0,size,"Verificare SHA-256");
            if(source.length()!=size||source.lastModified()!=modified||temporary.length()!=size||!digest(source,progress,0,size*2).equals(digest(temporary,progress,size,size*2)))throw new IOException("Sursa s-a schimbat sau verificarea a eșuat");
            Files.move(temporary.toPath(),target.toPath());if(move){if(source.length()!=size||source.lastModified()!=modified||!source.delete())throw new IOException("Copiat și verificat; sursa nu a fost ștearsă");}if(progress!=null)progress.update(size,size,"Verificat");return target;
        }finally{if(temporary.exists())temporary.delete();}
    }
    static List<File> search(File root,String term)throws IOException{String needle=normal(term);if(needle.isEmpty())return Collections.emptyList();ArrayList<File> found=new ArrayList<File>();ArrayDeque<File> directories=new ArrayDeque<File>();HashSet<String> visited=new HashSet<String>();directories.add(root);int scanned=0;while(!directories.isEmpty()&&scanned<5000&&found.size()<200){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();File dir=directories.removeFirst();if(!inside(root,dir)||!visited.add(dir.getCanonicalPath()))continue;File[] files=dir.listFiles();if(files==null)continue;for(File file:files){if(++scanned>5000||found.size()>=200)break;if(Files.isSymbolicLink(file.toPath())||file.getName().startsWith(".leo-")||!inside(root,file))continue;if(file.isDirectory())directories.addLast(file);else if(file.isFile()&&normal(file.getName()).contains(needle))found.add(file);}}return found;}
    private static String normal(String value){return java.text.Normalizer.normalize(value.toLowerCase(java.util.Locale.ROOT),java.text.Normalizer.Form.NFD).replaceAll("\\p{M}+","");}
}
